//save latest 6 email timestamp. Every 1 hour, only allows 6 emails.
var emailTimestamps =[];
const max_email_per_hour = 6;
const second_6_hour = 6*60*60;

// send mail with defined transport object
exports.sendMail = function( msg, callback ) {

    console.log("will send email.");

    var now = Math.round(new Date() / 1000); //second since 1 Jan 1970
    emailTimestamps.push(now);

    if( max_email_per_hour < emailTimestamps.length ){
        console.log("7 email already");
        var oldestTimestamp = emailTimestamps.shift();
        console.log( "time diff : " + (now - oldestTimestamp));
        if( now - oldestTimestamp < second_6_hour ){
            callback( "too many email in last a few hours, please wait for a while. Thanks")
            return;
        }
    }

    console.log( "email: " + msg );
    var mailOptions = {
        from: '"Yang Guo" <yangguowebsite@gmail.com>', // sender address
        to: 'cerisemdt@gmail.com', // list of receivers
        subject: 'from My Website', // Subject line
        text: msg, // plain text body
        html: msg // html body
    };

    transporter.sendMail(mailOptions, function (error, info) {
        if (error) {
            return console.log("mail error:" + error);
            callback( "Sorry, something wrong :( Please try again. You can also reach me by Facebook." );
        }
        console.log('Message %s sent: %s', info.messageId, info.response);
        callback( "Your message has been sent. Thanks :)" );
    });
}